inline ::flatbuffers::Offset<PAP> CreatePAP(::flatbuffers::FlatBufferBuilder &_fbb, const PAPT *_o, const ::flatbuffers::rehasher_function_t *_rehasher) {
  return PAP::Pack(_fbb, _o, _rehasher);
}

