inline const PAP *GetPAP(const void *buf) {
  return ::flatbuffers::GetRoot<PAP>(buf);
}

inline const PAP *GetSizePrefixedPAP(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<PAP>(buf);
}

inline const char *PAPIdentifier() {
  return "$PAP";
}

inline bool PAPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, PAPIdentifier());
}

inline bool SizePrefixedPAPBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, PAPIdentifier(), true);
}

template <bool B = false>
inline bool VerifyPAPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<PAP>(PAPIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedPAPBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<PAP>(PAPIdentifier());
}

inline void FinishPAPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<PAP> root) {
  fbb.Finish(root, PAPIdentifier());
}

inline void FinishSizePrefixedPAPBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<PAP> root) {
  fbb.FinishSizePrefixed(root, PAPIdentifier());
}

inline std::unique_ptr<PAPT> UnPackPAP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<PAPT>(GetPAP(buf)->UnPack(res));
}

inline std::unique_ptr<PAPT> UnPackSizePrefixedPAP(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<PAPT>(GetSizePrefixedPAP(buf)->UnPack(res));
}

